#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long t;
    cin >> n >> t;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int full = (1 << n) - 1;
    vector<int> sessions(full + 1, (int)n + 1), load(full + 1, 0);
    sessions[0] = 1;
    for (int mask = 0; mask <= full; mask++) {
        for (int i = 0; i < n; i++) {
            if ((mask >> i) & 1) continue;
            int ns, nl;
            if (load[mask] + a[i] <= t) {
                ns = sessions[mask];
                nl = load[mask] + (int)a[i];
            } else {
                ns = sessions[mask] + 1;
                nl = (int)a[i];
            }
            int to = mask | (1 << i);
            if (ns < sessions[to] || (ns == sessions[to] && nl < load[to])) {
                sessions[to] = ns;
                load[to] = nl;
            }
        }
    }
    cout << sessions[full] << "\n";

    return 0;
}

