import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long t = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();

        int full = (1 << (int) n) - 1;
        int[] sessions = new int[full + 1];
        int[] load = new int[full + 1];
        Arrays.fill(sessions, (int) n + 1);
        sessions[0] = 1;
        for (int mask = 0; mask <= full; mask++) {
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) != 0) continue;
                int ns, nl;
                if (load[mask] + a[i] <= t) {
                    ns = sessions[mask];
                    nl = load[mask] + (int) a[i];
                } else {
                    ns = sessions[mask] + 1;
                    nl = (int) a[i];
                }
                int to = mask | (1 << i);
                if (ns < sessions[to] || (ns == sessions[to] && nl < load[to])) {
                    sessions[to] = ns;
                    load[to] = nl;
                }
            }
        }
        System.out.println(sessions[full]);
    }
}
